#include "xgl3d.h"

static int append_char(char *out, unsigned long cap, unsigned long *len, char c)
{
    if (*len + 1UL >= cap) return 0;
    out[*len] = c;
    (*len)++;
    out[*len] = '\0';
    return 1;
}

static int append_str(char *out, unsigned long cap, unsigned long *len, const char *s)
{
    while (*s != '\0') {
        if (!append_char(out, cap, len, *s)) return 0;
        ++s;
    }
    return 1;
}

static int append_uint(char *out, unsigned long cap, unsigned long *len, unsigned long v)
{
    char buf[16];
    int i;
    int n;
    if (v == 0UL) return append_char(out, cap, len, '0');
    n = 0;
    while (v != 0UL && n < 16) { buf[n++] = (char)('0' + (v % 10UL)); v /= 10UL; }
    i = n - 1;
    while (i >= 0) { if (!append_char(out, cap, len, buf[i])) return 0; --i; }
    return 1;
}

static int append_fixed(char *out, unsigned long cap, unsigned long *len, xgl3d_fixed v)
{
    long whole;
    long frac;
    int neg;
    if (v < 0L) { neg = 1; v = -v; } else neg = 0;
    whole = v >> 16;
    frac = ((v & 65535L) * 10000L) >> 16;
    if (neg) { if (!append_char(out, cap, len, '-')) return 0; }
    if (!append_uint(out, cap, len, (unsigned long)whole)) return 0;
    if (!append_char(out, cap, len, '.')) return 0;
    if (frac < 1000L) { if (!append_char(out, cap, len, '0')) return 0; }
    if (frac < 100L) { if (!append_char(out, cap, len, '0')) return 0; }
    if (frac < 10L) { if (!append_char(out, cap, len, '0')) return 0; }
    if (!append_uint(out, cap, len, (unsigned long)frac)) return 0;
    return 1;
}

static int append_v3(char *out, unsigned long cap, unsigned long *len, xgl3d_vec3 v)
{
    if (!append_fixed(out, cap, len, v.x)) return 0;
    if (!append_char(out, cap, len, ' ')) return 0;
    if (!append_fixed(out, cap, len, v.y)) return 0;
    if (!append_char(out, cap, len, ' ')) return 0;
    if (!append_fixed(out, cap, len, v.z)) return 0;
    return 1;
}

static int append_v2(char *out, unsigned long cap, unsigned long *len, xgl3d_vec2 v)
{
    if (!append_fixed(out, cap, len, v.x)) return 0;
    if (!append_char(out, cap, len, ' ')) return 0;
    if (!append_fixed(out, cap, len, v.y)) return 0;
    return 1;
}

int xgl3d_write_obj_to_buffer(const xgl3d_model *m, char *out, unsigned long cap, unsigned long *len_out)
{
    unsigned long len;
    int i;
    int a;
    int b;
    int c;
    if (m == 0 || out == 0 || len_out == 0) return XGL3D_E_NULL;
    len = 0UL;
    if (cap == 0UL) return XGL3D_E_CAPACITY;
    out[0] = '\0';
    if (!append_str(out, cap, &len, "# generated by xgl3d C89 fixed-point decoder\n")) return XGL3D_E_CAPACITY;
    i = 0;
    while (i < m->vertex_count) {
        if (!append_str(out, cap, &len, "v ")) return XGL3D_E_CAPACITY;
        if (!append_v3(out, cap, &len, m->vertices[i].pos)) return XGL3D_E_CAPACITY;
        if (!append_char(out, cap, &len, '\n')) return XGL3D_E_CAPACITY;
        ++i;
    }
    i = 0;
    while (i < m->vertex_count) {
        if ((m->vertices[i].flags & XGL3D_FV_HAS_TC) != 0U) {
            if (!append_str(out, cap, &len, "vt ")) return XGL3D_E_CAPACITY;
            if (!append_v2(out, cap, &len, m->vertices[i].texcoord)) return XGL3D_E_CAPACITY;
            if (!append_char(out, cap, &len, '\n')) return XGL3D_E_CAPACITY;
        }
        ++i;
    }
    i = 0;
    while (i < m->vertex_count) {
        if ((m->vertices[i].flags & XGL3D_FV_HAS_N) != 0U) {
            if (!append_str(out, cap, &len, "vn ")) return XGL3D_E_CAPACITY;
            if (!append_v3(out, cap, &len, m->vertices[i].normal)) return XGL3D_E_CAPACITY;
            if (!append_char(out, cap, &len, '\n')) return XGL3D_E_CAPACITY;
        }
        ++i;
    }
    i = 0;
    while (i < m->triangle_count) {
        a = m->triangles[i].v[0] + 1;
        b = m->triangles[i].v[1] + 1;
        c = m->triangles[i].v[2] + 1;
        if (!append_str(out, cap, &len, "f ")) return XGL3D_E_CAPACITY;
        if (!append_uint(out, cap, &len, (unsigned long)a)) return XGL3D_E_CAPACITY;
        if (!append_char(out, cap, &len, ' ')) return XGL3D_E_CAPACITY;
        if (!append_uint(out, cap, &len, (unsigned long)b)) return XGL3D_E_CAPACITY;
        if (!append_char(out, cap, &len, ' ')) return XGL3D_E_CAPACITY;
        if (!append_uint(out, cap, &len, (unsigned long)c)) return XGL3D_E_CAPACITY;
        if (!append_char(out, cap, &len, '\n')) return XGL3D_E_CAPACITY;
        ++i;
    }
    *len_out = len;
    return XGL3D_OK;
}

static int append_mat_name(char *out, unsigned long cap, unsigned long *len, int mi)
{
    if (!append_str(out, cap, len, "mat_")) return 0;
    return append_uint(out, cap, len, (unsigned long)(mi < 0 ? 0 : mi));
}

static int append_mtl_color(char *out, unsigned long cap, unsigned long *len, const char *key, xgl3d_color c)
{
    if (!append_str(out, cap, len, key)) return 0;
    if (!append_char(out, cap, len, ' ')) return 0;
    if (!append_fixed(out, cap, len, c.r)) return 0;
    if (!append_char(out, cap, len, ' ')) return 0;
    if (!append_fixed(out, cap, len, c.g)) return 0;
    if (!append_char(out, cap, len, ' ')) return 0;
    if (!append_fixed(out, cap, len, c.b)) return 0;
    return append_char(out, cap, len, '\n');
}

static int write_mtl(const xgl3d_model *m, char *out, unsigned long cap, unsigned long *len_out)
{
    unsigned long len;
    int i;
    int tex;
    if (m == 0 || out == 0 || len_out == 0) return XGL3D_E_NULL;
    len = 0UL;
    if (cap == 0UL) return XGL3D_E_CAPACITY;
    out[0] = '\0';
    if (!append_str(out, cap, &len, "# generated by xgl3d\n")) return XGL3D_E_CAPACITY;
    i = 0;
    while (i < m->material_count) {
        if (!append_str(out, cap, &len, "newmtl ")) return XGL3D_E_CAPACITY;
        if (!append_mat_name(out, cap, &len, i)) return XGL3D_E_CAPACITY;
        if (!append_char(out, cap, &len, '\n')) return XGL3D_E_CAPACITY;
        if (!append_mtl_color(out, cap, &len, "Ka", m->materials[i].ambient)) return XGL3D_E_CAPACITY;
        if (!append_mtl_color(out, cap, &len, "Kd", m->materials[i].diffuse)) return XGL3D_E_CAPACITY;
        if (!append_mtl_color(out, cap, &len, "Ks", m->materials[i].specular)) return XGL3D_E_CAPACITY;
        if (!append_str(out, cap, &len, "d ")) return XGL3D_E_CAPACITY;
        if (!append_fixed(out, cap, &len, m->materials[i].alpha)) return XGL3D_E_CAPACITY;
        if (!append_char(out, cap, &len, '\n')) return XGL3D_E_CAPACITY;
        if (!append_str(out, cap, &len, "Ns ")) return XGL3D_E_CAPACITY;
        if (!append_fixed(out, cap, &len, m->materials[i].shininess)) return XGL3D_E_CAPACITY;
        if (!append_char(out, cap, &len, '\n')) return XGL3D_E_CAPACITY;
        tex = m->materials[i].texture_index;
        if (tex >= 0 && tex < m->texture_count && m->textures[tex].ref[0] != '\0') {
            if (!append_str(out, cap, &len, "map_Kd ")) return XGL3D_E_CAPACITY;
            if (!append_str(out, cap, &len, m->textures[tex].ref)) return XGL3D_E_CAPACITY;
            if (!append_char(out, cap, &len, '\n')) return XGL3D_E_CAPACITY;
        }
        if (!append_char(out, cap, &len, '\n')) return XGL3D_E_CAPACITY;
        ++i;
    }
    *len_out = len;
    return XGL3D_OK;
}

static int write_obj_v3(char *out, unsigned long cap, unsigned long *len, const char *prefix, xgl3d_vec3 v)
{
    if (!append_str(out, cap, len, prefix)) return 0;
    if (!append_v3(out, cap, len, v)) return 0;
    return append_char(out, cap, len, '\n');
}

static int write_obj_v2(char *out, unsigned long cap, unsigned long *len, const char *prefix, xgl3d_vec2 v)
{
    if (!append_str(out, cap, len, prefix)) return 0;
    if (!append_v2(out, cap, len, v)) return 0;
    return append_char(out, cap, len, '\n');
}

static int append_face_idx(char *out, unsigned long cap, unsigned long *len, int idx)
{
    unsigned long v;
    v = (unsigned long)(idx + 1);
    if (!append_uint(out, cap, len, v)) return 0;
    if (!append_char(out, cap, len, '/')) return 0;
    if (!append_uint(out, cap, len, v)) return 0;
    if (!append_char(out, cap, len, '/')) return 0;
    return append_uint(out, cap, len, v);
}

int xgl3d_write_obj_mtl_to_buffers(const xgl3d_model *m, const char *mtl_name, char *obj_out, unsigned long obj_cap, unsigned long *obj_len_out, char *mtl_out, unsigned long mtl_cap, unsigned long *mtl_len_out)
{
    unsigned long len;
    int i;
    int mat;
    int last_mat;
    int base;
    int a;
    int b;
    int c;
    if (m == 0 || obj_out == 0 || obj_len_out == 0) return XGL3D_E_NULL;
    if (obj_cap == 0UL) return XGL3D_E_CAPACITY;
    len = 0UL;
    obj_out[0] = '\0';
    if (!append_str(obj_out, obj_cap, &len, "# generated by xgl3d C89 fixed-point decoder\n")) return XGL3D_E_CAPACITY;
    if (mtl_name != 0 && mtl_name[0] != '\0') {
        if (!append_str(obj_out, obj_cap, &len, "mtllib ")) return XGL3D_E_CAPACITY;
        if (!append_str(obj_out, obj_cap, &len, mtl_name)) return XGL3D_E_CAPACITY;
        if (!append_char(obj_out, obj_cap, &len, '\n')) return XGL3D_E_CAPACITY;
    }
    i = 0;
    while (i < m->vertex_count) { if (!write_obj_v3(obj_out, obj_cap, &len, "v ", m->vertices[i].pos)) return XGL3D_E_CAPACITY; ++i; }
    i = 0;
    while (i < m->line_count) {
        if (!write_obj_v3(obj_out, obj_cap, &len, "v ", m->lines[i].v[0].pos)) return XGL3D_E_CAPACITY;
        if (!write_obj_v3(obj_out, obj_cap, &len, "v ", m->lines[i].v[1].pos)) return XGL3D_E_CAPACITY;
        ++i;
    }
    i = 0;
    while (i < m->point_count) { if (!write_obj_v3(obj_out, obj_cap, &len, "v ", m->points[i].v.pos)) return XGL3D_E_CAPACITY; ++i; }
    i = 0;
    while (i < m->vertex_count) { if (!write_obj_v2(obj_out, obj_cap, &len, "vt ", m->vertices[i].texcoord)) return XGL3D_E_CAPACITY; ++i; }
    i = 0;
    while (i < m->vertex_count) { if (!write_obj_v3(obj_out, obj_cap, &len, "vn ", m->vertices[i].normal)) return XGL3D_E_CAPACITY; ++i; }
    last_mat = XGL3D_INVALID_INDEX;
    i = 0;
    while (i < m->triangle_count) {
        mat = m->triangles[i].material_index;
        if (mat != last_mat && mat >= 0 && mat < m->material_count) {
            if (!append_str(obj_out, obj_cap, &len, "usemtl ")) return XGL3D_E_CAPACITY;
            if (!append_mat_name(obj_out, obj_cap, &len, mat)) return XGL3D_E_CAPACITY;
            if (!append_char(obj_out, obj_cap, &len, '\n')) return XGL3D_E_CAPACITY;
            last_mat = mat;
        }
        a = m->triangles[i].v[0]; b = m->triangles[i].v[1]; c = m->triangles[i].v[2];
        if (!append_str(obj_out, obj_cap, &len, "f ")) return XGL3D_E_CAPACITY;
        if (!append_face_idx(obj_out, obj_cap, &len, a)) return XGL3D_E_CAPACITY;
        if (!append_char(obj_out, obj_cap, &len, ' ')) return XGL3D_E_CAPACITY;
        if (!append_face_idx(obj_out, obj_cap, &len, b)) return XGL3D_E_CAPACITY;
        if (!append_char(obj_out, obj_cap, &len, ' ')) return XGL3D_E_CAPACITY;
        if (!append_face_idx(obj_out, obj_cap, &len, c)) return XGL3D_E_CAPACITY;
        if (!append_char(obj_out, obj_cap, &len, '\n')) return XGL3D_E_CAPACITY;
        ++i;
    }
    base = m->vertex_count;
    i = 0;
    while (i < m->line_count) {
        if (!append_str(obj_out, obj_cap, &len, "l ")) return XGL3D_E_CAPACITY;
        if (!append_uint(obj_out, obj_cap, &len, (unsigned long)(base + i * 2 + 1))) return XGL3D_E_CAPACITY;
        if (!append_char(obj_out, obj_cap, &len, ' ')) return XGL3D_E_CAPACITY;
        if (!append_uint(obj_out, obj_cap, &len, (unsigned long)(base + i * 2 + 2))) return XGL3D_E_CAPACITY;
        if (!append_char(obj_out, obj_cap, &len, '\n')) return XGL3D_E_CAPACITY;
        ++i;
    }
    base = m->vertex_count + m->line_count * 2;
    i = 0;
    while (i < m->point_count) {
        if (!append_str(obj_out, obj_cap, &len, "p ")) return XGL3D_E_CAPACITY;
        if (!append_uint(obj_out, obj_cap, &len, (unsigned long)(base + i + 1))) return XGL3D_E_CAPACITY;
        if (!append_char(obj_out, obj_cap, &len, '\n')) return XGL3D_E_CAPACITY;
        ++i;
    }
    *obj_len_out = len;
    if (mtl_out != 0 && mtl_len_out != 0) return write_mtl(m, mtl_out, mtl_cap, mtl_len_out);
    return XGL3D_OK;
}
